	args = append(args, "--", patchFile)
	cmd := exec.Command("git", args...)
	cmd.Dir = checkout
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("apply %s: %w\n%s", patchFile, err, bytes.TrimSpace(out))
	}
	return nil
}

